      "path": "src/core/runtime.js",
      "content": "import fs from 'node:fs'\nimport path from 'node:path'\nimport { FreeModelAdapter, ROUTE_MAIN, ROUTE_REGION } from '../adapter.js'\nimport { buildCatalog, buildEacCatalog, buildKiloCatalog, isEacEntry, isKiloEntry, parseListing, reviveKiloCatalog } from '../catalog.js'\nimport { buildAggregateCatalog, isAggregateEntry } from '../aggregate.js'\nimport { buildComboCatalog, isComboEntry, normalizeCombos, pruneRotation } from '../combos.js'\nimport { JsonStore, SETTINGS_INITIAL, STATS_INITIAL, STATS_VERSION, migrateStats, pruneDays, recordTurn, recordUsage, isModelHidden } from '../store.js'\nimport { STATE, detectEgress, probeCatalog } from '../probe.js'\nimport { CODE, UpstreamError, getJson } from '../http.js'\nimport { runModelTest, modelAvailability } from '../model-test.js'\nimport { DEFAULT_LEVEL } from '../effort.js'\nimport { fetchSealedListing } from '../eac.js'\nimport { fetchKiloListing } from '../kilo.js'\nimport { sessionForConversation } from '../upstream.js'\nimport { createForwardCompletion, publicModelRows } from './completion.js'\nimport { isSubscriptionEntry, subscriptionCatalog } from '../subscription-adapter.js'\n\nconst FALLBACK_CATALOG = buildCatalog([\n  'mimo-v2.6-flash-free', 'mimo-v2.5-free', 'ling-3.0-flash-fin-free',\n  'nemotron-3-ultra-free', 'nemotron-3.5-lightning-free', 'space-bunny-free',\n  'muse-spark-1.3-contributor-free', 'muse-spark-1.2-contributor-free',\n])\n\n/** 路径由产品入口决定；核心不解析 DSH_HOME，也不发现宿主服务。 */\nexport function createRuntimeStores({ dataDir, logger = console }) {\n  if (typeof dataDir !== 'string' || !path.isAbsolute(dataDir)) {\n    throw new TypeError('dataDir must be an absolute path')\n  }\n  fs.mkdirSync(dataDir, { recursive: true, mode: 0o700 })\n  const open = (file, initial) => new JsonStore(path.join(dataDir, file), structuredClone(initial), {\n    log: message => logger.warn?.(message),\n  })\n  // Seed the recommended combo only for a genuinely fresh install. Existing\n  // settings files that predate combos must not gain a new advertised model\n  // merely because a new default was added to SETTINGS_INITIAL; user edits to\n  // an existing `combos` field still win through JsonStore's normal merge.\n  const settingsInitial = structuredClone(SETTINGS_INITIAL)\n  const settingsPath = path.join(dataDir, 'settings.json')\n  if (fs.existsSync(settingsPath)) settingsInitial.combos = []\n  const settings = new JsonStore(settingsPath, settingsInitial, {\n    log: message => logger.warn?.(message),\n  })\n  const stats = open('stats.json', STATS_INITIAL)\n  const availability = open('availability.json', { version: 1, at: 0, egress: null, results: {} })\n  const catalogStore = open('catalog.json', { version: 1, at: 0, entries: FALLBACK_CATALOG.map(entry => entry.id) })\n  if (stats.get().version !== STATS_VERSION) stats.edit(migrateStats)\n  return {\n    settings, stats, availability, catalogStore,\n    dispose() {\n      settings.dispose(); stats.dispose(); availability.dispose(); catalogStore.dispose()\n    },\n  }\n}\n\n/**\n * 两个产品共同使用的模型运行时。宿主仅注入能力，不传入 Cordis ctx。\n * 创建不启动网络任务；入口先绑定本地监听器，再决定何时刷新和探测。\n * Optional subscriptionRuntime supplies catalog() and complete(request, onChunk);\n * its helper owns accounting. Call syncAggregateCatalog() after account mutations.\n */\nexport function createModelRuntime({\n  settings, stats, availability, catalogStore,\n  logger = console,\n  attributionUserAgent = 'our-free-model',\n  resolveImage,\n  sealedCredential = () => null,\n  onSealedUnavailable = () => {},\n  onTopology = () => {},\n  subscriptionRuntime,\n}) {\n  let catalog = materializeCatalog(catalogStore.get().entries ?? [])\n  let sealedCatalog = sealedCredential() === null ? [] : buildEacCatalog(catalogStore.get().sealIds ?? [])\n  let kiloCatalog = reviveKiloCatalog(catalogStore.get().kiloRows)\n  /** The aggregate lane: one row per enabled provider/model the user configured.\n   *  Derived from settings, not from a listing, so it is rebuilt on every merge. */\n  let aggregateCatalog = []\n  let subscriptionEntries = []\n  /** The virtual rows a combo contributes; rebuilt last, after every real lane. */\n  let comboCatalog = []\n  /** The free lane's own roster: the base every other lane is merged onto. */\n  let freeCatalog = catalog\n  let egress = availability.get().egress ?? null\n  let gatewayLatency = { ms: 0, at: 0 }\n  let disposed = false\n  const lifetime = new AbortController()\n  let egressGeneration = 0\n\n  /**\n   * Rebuild the merged catalog from its parts, in precedence order.\n   *\n   * Rebuilt rather than appended to, because every one of these lists can shrink:\n   * a provider the user switched off, a chain whose head was removed, a Kilo\n   * model that went paid. Appending only ever grew the view, so a removed row\n   * stayed dialable until the next full listing round happened to reset it.\n   *\n   * Combos come last on purpose — a chain's links have to already exist as real\n   * rows, which is also what makes `buildComboCatalog` drop a link that is gone\n   * instead of keeping a hopeful placeholder.\n   */\n  const rebuildCatalog = () => {\n    const seen = new Set()\n    const merged = []\n    for (const entry of [...freeCatalog, ...sealedCatalog, ...kiloCatalog, ...aggregateCatalog, ...subscriptionEntries]) {\n      if (entry === null || entry === undefined || seen.has(entry.id)) continue\n      seen.add(entry.id)\n      merged.push(entry)\n    }\n    const combos = normalizeCombos(settings.get().combos)\n    comboCatalog = buildComboCatalog(combos, merged)\n    pruneRotation(combos)\n    for (const entry of comboCatalog) {\n      if (seen.has(entry.id)) continue\n      seen.add(entry.id)\n      merged.push(entry)\n    }\n    catalog = merged\n  }\n  const mergeCatalogs = () => {\n    aggregateCatalog = buildAggregateCatalog(settings.get().aggregate ?? {})\n    subscriptionEntries = subscriptionCatalog(subscriptionRuntime)\n    rebuildCatalog()\n  }\n  mergeCatalogs()\n  const state = () => ({\n    catalog,\n    membership: computeMembership(catalog, availability.get(), settings.get()),\n    settings: settings.get(),\n    attributionUserAgent,\n    routing: {\n      quota: subscriptionRuntime?.routingQuota?.() ?? {},\n      usage: Object.fromEntries(catalog.map(row => [row.id, stats.get().models?.[row.id]?.calls ?? 0])),\n    },\n  })\n  const emitTopology = () => { if (!disposed) onTopology() }\n  const adapter = new FreeModelAdapter({\n    state,\n    resolveImage,\n    subscriptionRuntime,\n    sealedCredential,\n    recordUsage: record => {\n      if (disposed) return\n      recordUsage(stats, record)\n      stats.edit(value => pruneDays(value, 120))\n    },\n    recordTurn: record => { if (!disposed) recordTurn(stats, record) },\n    warn: message => logger.warn?.(message) ?? logger.log?.(message),\n    // Automatic probing is disabled by owner policy: a region refusal from a\n    // real turn stays a turn failure and never fires a background probe.\n  })\n\n  // 手动强制刷新不能借用一个因限流而跳过探测的普通刷新。\n  let catalogRefresh = null\n  let catalogRefreshForced = false\n  let catalogRefreshProbed = false\n  async function refreshCatalog(opts) {\n    // Automatic probing is disabled by owner policy: `probe` defaults to false\n    // and every automatic caller passes false. Only an explicit user action (the\n    // reprobe button or an explicit caller) asks for `probe: true`.\n    const { probe = false, force = false } = opts ?? {}\n    if (disposed) return catalog\n    while (catalogRefresh !== null) {\n      const shared = catalogRefresh\n      const sharedForced = catalogRefreshForced\n      const sharedProbed = catalogRefreshProbed\n      const value = await shared\n      if (disposed || ((!force || sharedForced) && (!probe || sharedProbed))) return value\n    }\n    const run = refreshCatalogOnce({ probe, force })\n    catalogRefresh = run\n    catalogRefreshForced = force\n    catalogRefreshProbed = probe\n    try { return await run } finally {\n      if (catalogRefresh === run) {\n        catalogRefresh = null; catalogRefreshForced = false; catalogRefreshProbed = false\n      }\n    }\n  }\n\n  async function refreshCatalogOnce({ probe, force }) {\n    let ids = []\n    try {\n      ids = parseListing(await fetchListing())\n    } catch (error) {\n      if (!disposed) logger.warn?.(`our-free-model: model listing refresh failed (${error?.message ?? error}); keeping the cached catalog`)\n    }\n    if (disposed) return catalog\n    if (ids.length > 0) {\n      freeCatalog = buildCatalog(ids)\n      catalogStore.update({ at: Date.now(), entries: freeCatalog.map(entry => entry.id) })\n      catalogStore.flush()\n      settings.update({ catalogSyncedAt: Date.now() })\n    } else {\n      freeCatalog = materializeCatalog(catalogStore.get().entries ?? [])\n    }\n    await refreshSealedRoster()\n    if (disposed) return catalog\n    await refreshKiloRoster()\n    if (disposed) return catalog\n    mergeCatalogs()\n    if (probe) await refreshAvailability(force)\n    emitTopology()\n    return catalog\n  }\n\n  async function refreshSealedRoster() {\n    const credential = sealedCredential()\n    if (credential === null) {\n      sealedCatalog = []\n      onSealedUnavailable()\n      return\n    }\n    try {\n      const ids = parseListing(await fetchSealedListing(credential, { signal: lifetime.signal }))\n      if (disposed) return\n      // 独立应用授权变更时，旧账号正在返回的清单不得覆盖新状态。\n      if (Object.hasOwn(credential, 'userToken') && sealedCredential()?.userToken !== credential.userToken) return\n      if (ids.length > 0) {\n        sealedCatalog = buildEacCatalog(ids)\n        catalogStore.update({ sealIds: sealedCatalog.map(entry => entry.id) })\n      }\n    } catch (error) {\n      if (disposed) return\n      if (Object.hasOwn(credential, 'userToken') && sealedCredential()?.userToken !== credential.userToken) return\n      if (error?.code === CODE.credential) {\n        sealedCatalog = []\n        catalogStore.update({ sealIds: [] })\n        logger.warn?.('our-free-model: the sealed lane refused its credential; its models are hidden until it is accepted again')\n        return\n      }\n      logger.warn?.(`our-free-model: sealed lane listing failed (${error?.code ?? 'unknown'}); keeping its cached roster`)\n    }\n  }\n\n  async function refreshSealedLane() {\n    await refreshSealedRoster()\n    if (disposed) return\n    // The rebuild in `mergeCatalogs` drops a stale roster on its own: a closed\n    // lane's rows vanish without a filter pass over the merged view.\n    mergeCatalogs()\n    emitTopology()\n  }\n\n  async function refreshKiloRoster() {\n    try {\n      const payload = await fetchKiloListing({ signal: lifetime.signal })\n      if (disposed) return\n      if (payload?.error || !Array.isArray(payload?.data)) throw new Error('invalid Kilo model listing')\n      kiloCatalog = buildKiloCatalog(payload.data)\n      catalogStore.update({ kiloRows: kiloCatalog })\n    } catch (error) {\n      if (!disposed) logger.warn?.(`our-free-model: Kilo channel listing failed (${error?.code ?? error?.message ?? 'unknown'}); keeping its cached roster`)\n    }\n  }\n\n  async function fetchListing() {\n    if (disposed) return { data: [] }\n    const started = Date.now()\n    const listing = await getJson('/inference/v1/models', {\n      session: sessionForConversation('catalog:our-free-model'),\n      attributionUserAgent,\n      signal: lifetime.signal,\n    })\n    if (!disposed) gatewayLatency = { ms: Date.now() - started, at: Date.now() }\n    return listing\n  }\n\n  let probeRound = null\n  let probeRoundGeneration = 0\n  let probeThrottleStreak = 0\n  let probeBackoffUntil = 0\n  async function runProbeRound() {\n    const generation = egressGeneration\n    // The absorbed channels get no per-model probes: their verdicts would be\n    // spent against a different gateway than the one that serves them, and a\n    // roster the listing named is advertised as-is (its health is the listing\n    // round's, refreshed on the same cadence). The aggregate lane is excluded\n    // for a sharper reason — a probe there is a *real request to a provider the\n    // user pays for*, spent to learn something the settings page already knows\n    // (whether a key is configured). A combo is excluded because it has no\n    // endpoint of its own: probing one would send the chain's own id to the free\n    // lane as a model name, spending quota to collect a verdict about nothing.\n    const probeable = catalog.filter(entry => !isEacEntry(entry) && !isKiloEntry(entry) && !isAggregateEntry(entry) && !isComboEntry(entry) && !isSubscriptionEntry(entry))\n    const results = await probeCatalog(probeable, { attributionUserAgent, signal: lifetime.signal }, (id, result) => {\n      if (disposed || generation !== egressGeneration) return\n      availability.edit(value => ({\n        ...value,\n        results: {\n          ...value.results,\n          [id]: {\n            state: result.state,\n            ...result.detail === undefined ? {} : { detail: result.detail },\n            ...result.ttftMs === undefined ? {} : { ttftMs: result.ttftMs },\n            latencyMs: result.latencyMs, startedAt: result.startedAt, at: Date.now(),\n          },\n        },\n      }))\n    }, 2)\n    if (disposed || generation !== egressGeneration) return {}\n    availability.update({ at: Date.now(), egress })\n    availability.flush()\n    const verdicts = Object.values(results)\n    if (verdicts.length > 0 && verdicts.every(row => row.state === STATE.unavailable)) {\n      logger.warn?.(`our-free-model: the gateway refused all ${verdicts.length} models this round (${verdicts[0].detail ?? 'no detail'}); keeping them advertised`)\n    }\n    const allThrottled = verdicts.length > 0 && verdicts.every(row => row.state === STATE.throttled)\n    probeThrottleStreak = allThrottled ? probeThrottleStreak + 1 : 0\n    probeBackoffUntil = allThrottled\n      ? Date.now() + Math.min(30 * 2 ** (probeThrottleStreak - 1), 120) * 60_000\n      : 0\n    if (allThrottled) {\n      logger.warn?.(`our-free-model: the probe round hit the lane's quota; availability probes pause for ${Math.round((probeBackoffUntil - Date.now()) / 60_000)} minutes (your own requests are unaffected, and the reprobe button forces a round)`)\n    }\n    emitTopology()\n    return results\n  }\n  async function refreshAvailability(force = false) {\n    if (disposed || (!force && probeBackoffUntil > Date.now())) return {}\n    if (probeRound !== null && probeRoundGeneration === egressGeneration) return probeRound\n    probeRoundGeneration = egressGeneration\n    const round = runProbeRound()\n    probeRound = round\n    try { return await round } finally { if (probeRound === round) probeRound = null }\n  }\n\n  async function watchEgress() {\n    if (disposed) return false\n    const seen = await detectEgress({ signal: lifetime.signal })\n    if (disposed || seen === undefined) return false\n    const previous = availability.get().egress\n    const changed = previous === null || previous === undefined\n      || previous.ip !== seen.ip || (seen.country !== undefined && previous.country !== seen.country)\n    egress = seen\n    if (changed) {\n      egressGeneration++\n      // 保留历史记录，但旧出口的成功、拒绝和手动测量均不能代表新出口。\n      const expire = rows => Object.fromEntries(Object.entries(rows ?? {}).map(([id, row]) => [id, { ...row, stale: true }]))\n      availability.edit(value => ({\n        ...value, egress: seen, at: 0,\n        results: expire(value.results), manualResults: expire(value.manualResults),\n      }))\n      availability.flush()\n      probeThrottleStreak = 0\n      probeBackoffUntil = 0\n      emitTopology()\n      // 只使旧判定失效并通知选择器，不发送任何自动探测请求。\n      logger.info?.(`our-free-model: egress changed to ${seen.ip}${seen.country ? ` (${seen.country})` : ''}; previous availability marked stale`)\n    }\n    return true\n  }\n\n  const latestTests = new Map()\n  async function testModel(id, effort = DEFAULT_LEVEL, { signal } = {}) {\n    if (disposed) throw new UpstreamError('Model runtime stopped', CODE.aborted)\n    if (settings.get().enabled === false) throw new UpstreamError('Inference is paused', CODE.client)\n    const entry = catalog.find(candidate => candidate.id === id)\n    if (!entry) throw new UpstreamError('Unknown model \"' + id + '\"', CODE.client, { status: 404 })\n    const token = {}\n    latestTests.set(id, token)\n    const generation = egressGeneration\n    const selectedEffort = effort === undefined || effort === '' ? DEFAULT_LEVEL : effort\n    const linkedSignal = signal ? AbortSignal.any([signal, lifetime.signal]) : lifetime.signal\n    const persist = row => {\n      if (disposed || linkedSignal.aborted || latestTests.get(id) !== token || generation !== egressGeneration) return false\n      availability.edit(value => ({ ...value, manualResults: { ...value.manualResults, [id]: row } }))\n      availability.flush()\n      emitTopology()\n      return !availability.writeFailed\n    }\n    try {\n      const measured = await runModelTest(testSignal => adapter.stream({\n        provider: ROUTE_MAIN, model: entry.id,\n        messages: [{ role: 'user', content: 'Reply with exactly: OK' }],\n        reasoningEffort: selectedEffort, sessionId: 'bench:' + entry.id + ':' + selectedEffort,\n        signal: testSignal,\n      }, entry, state()), { signal: linkedSignal })\n      if (linkedSignal.aborted || disposed) throw new UpstreamError('Text test cancelled', CODE.aborted)\n      if (generation !== egressGeneration) throw new UpstreamError('Network egress changed during the text test; please test again', CODE.aborted)\n      const persisted = persist({ state: STATE.available, source: 'manual', at: Date.now(), ttftMs: measured.ttftMs, latencyMs: measured.totalMs })\n      return { model: entry.id, effort: selectedEffort, ok: true, ...measured, persisted }\n    } catch (error) {\n      // Cancellation is a user action, not a fresh availability verdict. Other failures\n      // remain unknown instead of silently banning a paid/region-gated route.\n      if (error?.code !== CODE.aborted) persist({ state: STATE.unknown, source: 'manual', at: Date.now(), detail: String(error?.message ?? error).slice(0, 200) })\n      throw error\n    } finally {\n      if (latestTests.get(id) === token) latestTests.delete(id)\n    }\n  }\n\n  return {\n    testModel, state, adapter, refreshCatalog, refreshSealedLane, refreshAvailability, watchEgress, fetchListing,\n    complete: createForwardCompletion({\n      adapter, signal: lifetime.signal,\n      state: () => {\n        const snapshot = state()\n        // Hiding advertisements must not invalidate requests using a saved id.\n        return { ...snapshot, membership: computeMembership(snapshot.catalog, availability.get(), {\n          ...snapshot.settings, hiddenModelIds: [], hideFreeModels: false, hideEacModels: false,\n        }) }\n      },\n    }),\n    publicModelRows: () => publicModelRows(state()),\n    // A settings write that changes the aggregate lane or the chains (a key\n    // saved, a subscription imported/toggled/removed, a combo edited) rebuilds\n    // the merged view without an upstream listing round.\n    syncAggregateCatalog() {\n      if (disposed) return catalog\n      mergeCatalogs()\n      emitTopology()\n      return catalog\n    },\n    get catalog() { return catalog },\n    get egress() { return egress },\n    get gatewayLatency() { return gatewayLatency },\n    setAttributionUserAgent(value) { attributionUserAgent = value },\n    dispose() {\n      if (disposed) return\n      disposed = true\n      lifetime.abort()\n    },\n  }\n}\n\nfunction materializeCatalog(ids) {\n  const rebuilt = buildCatalog(ids)\n  return rebuilt.length > 0 ? rebuilt : FALLBACK_CATALOG\n}\n\nexport function computeMembership(catalog, availabilitySnapshot, settings) {\n  const expose = settings?.exposeRegionModels !== false\n  const verdictOf = entry => modelAvailability(entry.id, availabilitySnapshot, Boolean(entry.channel)).availability\n  const probeable = catalog.filter(entry => !entry.channel)\n  const refusedAll = probeable.length > 0 && probeable.every(entry => verdictOf(entry) === STATE.unavailable)\n  let usable = catalog.filter(entry => verdictOf(entry) !== STATE.unavailable)\n  if (refusedAll) usable = catalog\n  const main = []\n  const region = []\n  for (const entry of usable) {\n    if (isModelHidden(entry, settings)) continue\n    const verdict = verdictOf(entry)\n    if (verdict !== STATE.regionBlocked) main.push(entry.id)\n    else if (expose) region.push(entry.id)\n  }\n  const membership = {}\n  if (main.length > 0) membership[ROUTE_MAIN] = main\n  if (region.length > 0) membership[ROUTE_REGION] = region\n  return membership\n}\n"
    },
    {
      "path": "src/combos.js",
      "content": "/**\n * Combos: one model name that is really an ordered chain.\n *\n * The failure this exists for is not exotic. A quota wall, a region refusal, an\n * expired credential or a 5xx from one upstream all arrive as \"your turn died\",\n * even though three other lanes on this machine were idle and would have\n * answered. A combo turns that into a retry the user never sees: the chain is\n * walked in order, and the first candidate that produces output wins.\n *\n * A combo is a *virtual catalog entry*. It carries `channel: 'combo'` and a\n * `combo` list of real model ids, so the picker advertises it beside the real\n * models and the forward gateway dials it by name. `combo:` is the prefix, and\n * it is deliberately not a valid provider id — `parseProviderModelId` refuses\n * it, so an aggregate row can never be mistaken for a combo.\n *\n * Two strategies:\n *\n * - `fallback` — always start at the head of the list. Predictable, and the\n *   right choice when the list is a quality ladder.\n * - `round-robin` — start at the next candidate each turn (sticky for\n *   `stickyLimit` consecutive turns), so a chain of equivalent models spreads\n *   its load. The rotation cursor lives in memory: a restart losing it costs\n *   nothing but a different starting point.\n *\n * Capacities are the *intersection*, not the union. A chain that advertises\n * vision because its head supports it hands a fallback an image it cannot read;\n * a chain that advertises a 1M window because its head has one overruns a\n * fallback at 128K. The honest numbers are the ones every candidate can honour.\n *\n * @module src/combos.js\n */\n\nimport { createHash } from 'node:crypto'\n\nexport const COMBO_CHANNEL = 'combo'\nexport const COMBO_PREFIX = 'combo:'\nexport const COMBO_STRATEGIES = ['fallback', 'round-robin', 'smart', 'usage', 'pace']\n\n/** Rotation cursors, keyed by combo id. In-memory on purpose (see the header). */\nconst rotation = new Map()\n\nexport function isComboEntry(entry) {\n  return entry?.channel === COMBO_CHANNEL && Array.isArray(entry.combo)\n}\n\n/** `My Fast Chain` -> `combo:my-fast-chain`. */\nexport function comboId(name) {\n  const normalized = String(name ?? '').trim().toLowerCase()\n  if (normalized === '') return ''\n  const slug = normalized\n    .replace(/[^a-z0-9]+/g, '-')\n    .replace(/^-+|-+$/g, '')\n    .slice(0, 48)\n  // Non-Latin names still need a stable, URL-safe identity after a reload.\n  const identity = slug && !/[^\\x20-\\x7e]/.test(normalized) ? slug\n    : `${slug || 'u'}-${createHash('sha256').update(normalized).digest('hex').slice(0, 16)}`\n  return `${COMBO_PREFIX}${identity}`\n}\n\n/**\n * Coerce the stored settings value into a list of well-formed combos.\n *\n * A stored combo is user input that survived a JSON file, so every field is\n * treated as untrusted: a non-array `models` becomes empty (and the combo is\n * then dropped, because a chain with no links is a model that cannot answer),\n * a non-string id is dropped, and an unknown strategy falls back to `fallback`\n * rather than being honoured as a typo.\n */\nexport function normalizeCombos(raw) {\n  const rows = Array.isArray(raw) ? raw : []\n  const seen = new Set()\n  const out = []\n  for (const row of rows) {\n    if (row === null || typeof row !== 'object') continue\n    const id = typeof row.id === 'string' && row.id.startsWith(COMBO_PREFIX) ? row.id : comboId(row.name ?? row.id)\n    if (id === '' || seen.has(id)) continue\n    const models = [...new Set((Array.isArray(row.models) ? row.models : [])\n      .map(value => String(value ?? '').trim())\n      .filter(value => value !== '' && value !== id))]\n    if (models.length === 0) continue\n    seen.add(id)\n    out.push({\n      id,\n      name: String(row.name ?? '').trim() || id.slice(COMBO_PREFIX.length),\n      models,\n      strategy: COMBO_STRATEGIES.includes(row.strategy) ? row.strategy : 'fallback',\n      stickyLimit: Number.isFinite(Number(row.stickyLimit)) && Number(row.stickyLimit) > 0 ? Math.trunc(Number(row.stickyLimit)) : 1,\n      enabled: row.enabled !== false,\n    })\n  }\n  return out\n}\n\n/**\n * Build the virtual catalog rows for every enabled combo.\n *\n * Models that are not in the catalog *right now* are dropped from the chain\n * rather than kept as a hopeful entry: a chain whose second link does not exist\n * would report \"tried 2 candidates\" for a turn that only ever had one. The\n * combo itself disappears when fewer than one candidate survives, which is the\n * same rule the picker applies to a lane with no models.\n *\n * @param {Array<object>} combos - from `normalizeCombos`\n * @param {Array<object>} catalog - every real catalog entry\n */\nexport function buildComboCatalog(combos, catalog) {\n  const byId = new Map()\n  for (const entry of catalog) if (!isComboEntry(entry)) byId.set(entry.id, entry)\n  const definitions = new Map(combos.map(combo => [combo.id, combo]))\n  const visits = new Map()\n  const invalid = new Set()\n  const cycle = id => {\n    if (visits.get(id) === 1) return true\n    if (visits.get(id) === 2) return invalid.has(id)\n    const row = definitions.get(id)\n    if (!row || row.enabled === false) return false\n    visits.set(id, 1)\n    const bad = row.models.filter(model => definitions.has(model)).some(model => cycle(model))\n    visits.set(id, 2)\n    if (bad) invalid.add(id)\n    return bad\n  }\n  for (const combo of combos) cycle(combo.id)\n  const built = new Map()\n  const resolve = (combo, path = new Set()) => {\n    if (built.has(combo.id)) return built.get(combo.id)\n    if (combo.enabled === false || invalid.has(combo.id) || path.has(combo.id)) return null\n    const branch = new Set([...path, combo.id])\n    let cycle = false\n    const members = combo.models.map(id => {\n      if (byId.has(id)) return byId.get(id)\n      const nested = definitions.get(id)\n      if (!nested) return null\n      if (branch.has(id)) { cycle = true; return null }\n      const child = resolve(nested, branch)\n      if (child === null && nested.enabled !== false && nested.models.some(model => branch.has(model))) cycle = true\n      return child\n    }).filter(Boolean)\n    if (cycle || members.length === 0) return null\n    const entry = {\n      id: combo.id, name: combo.name, channel: COMBO_CHANNEL,\n      combo: members.map(member => member.id), strategy: combo.strategy, stickyLimit: combo.stickyLimit,\n      vision: members.every(member => member.vision === true),\n      reasoning: members.some(member => member.reasoning === true),\n      contextWindow: Math.min(...members.map(member => number(member.contextWindow) ?? 131072)),\n      maxOutput: Math.min(...members.map(member => number(member.maxOutput) ?? 32768)),\n      canDisableThinking: members.every(member => member.canDisableThinking !== false),\n      regionSensitive: false, wire: 'chat',\n      lanes: [...new Set(members.flatMap(member => member.lanes ?? [member.channel ?? 'free']))],\n    }\n    built.set(combo.id, entry)\n    return entry\n  }\n  const out = []\n  for (const combo of combos) {\n    const entry = resolve(combo)\n    if (entry) out.push(entry)\n  }\n  return out\n}\n\nfunction number(value) {\n  return typeof value === 'number' && Number.isFinite(value) && value > 0 ? Math.trunc(value) : undefined\n}\n\n/**\n * Resolve a combo row into the ordered candidate entries for one turn.\n *\n * `fallback` returns the list as stored. `round-robin` rotates the starting\n * point and then keeps it for `stickyLimit` turns, which is the behaviour the\n * upstream router settled on: a strict per-turn rotation defeats prompt caching\n * on every provider in the chain, and a strictly sticky cursor makes the other\n * candidates decoration.\n *\n * @param {object} entry - a combo catalog row\n * @param {Array<object>} catalog\n * @param {{peek?: boolean}} [options] - `peek` computes the order without consuming a turn\n */\nexport function comboChain(entry, catalog, options = {}) {\n  const ids = Array.isArray(entry?.combo) ? entry.combo : []\n  const byId = new Map()\n  for (const row of catalog) byId.set(row.id, row)\n  const path = new Set(options.path ?? [])\n  if (path.has(entry?.id)) return []\n  path.add(entry?.id)\n  const dedup = new Set()\n  const members = ids.flatMap(id => {\n    const row = byId.get(id)\n    return row ? isComboEntry(row) ? comboChain(row, catalog, { ...options, path }) : [row] : []\n  }).filter(row => { if (dedup.has(row.id)) return false; dedup.add(row.id); return true })\n  if (members.length <= 1) return members\n  if (['smart', 'usage', 'pace'].includes(entry.strategy)) {\n    const now = Number.isFinite(options.now) ? options.now : Date.now()\n    const readings = row => {\n      const quota = options.quota?.[row.id]\n      const checked = Date.parse(quota?.checkedAt ?? '')\n      if (!quota || !['ok', 'available'].includes(quota.status) || !Number.isFinite(checked) || now - checked > 15 * 60_000 || checked > now + 60_000) return []\n      return (quota.windows ?? []).filter(window => {\n        const reset = Date.parse(window.resetsAt ?? '')\n        return typeof window.remainingPercent === 'number' && window.remainingPercent >= 0 && window.remainingPercent <= 100\n          && (!Number.isFinite(reset) || reset > now)\n      })\n    }\n    const score = (row, index) => {\n      const windows = readings(row)\n      const exhausted = windows.some(window => window.remainingPercent <= 0)\n      const reset = Math.min(...windows.filter(window => window.remainingPercent > 0)\n        .map(window => Date.parse(window.resetsAt ?? '')).filter(Number.isFinite))\n      const weekly = windows.find(window => window.kind === 'weekly' || window.windowSeconds === 604800)\n      const hours = weekly ? (Date.parse(weekly.resetsAt ?? '') - now) / 3600000 : NaN\n      const pace = weekly && Number.isFinite(hours) && hours > 0 ? weekly.remainingPercent / Math.max(hours, 1 / 60) : null\n      const use = options.usage?.[row.id]\n      const usage = typeof use === 'number' && Number.isFinite(use) && use >= 0 ? use : null\n      return { row, index, exhausted, known: windows.length > 0, reset, pace, usage }\n    }\n    return members.map(score).sort((left, right) => {\n      if (left.exhausted !== right.exhausted) return left.exhausted ? 1 : -1\n      if (entry.strategy === 'usage') {\n        if ((left.usage !== null) !== (right.usage !== null)) return left.usage !== null ? -1 : 1\n        if (left.usage !== null && right.usage !== null && left.usage !== right.usage) return left.usage - right.usage\n      } else if (entry.strategy === 'pace') {\n        if ((left.pace !== null) !== (right.pace !== null)) return left.pace !== null ? -1 : 1\n        if (left.pace !== null && right.pace !== null && left.pace !== right.pace) return right.pace - left.pace\n      } else {\n        if (left.known !== right.known) return left.known ? -1 : 1\n        if (left.reset !== right.reset) return left.reset - right.reset\n      }\n      return left.index - right.index\n    }).filter(value => !value.exhausted).map(value => value.row)\n  }\n  if (entry.strategy !== 'round-robin') return members\n  const limit = Number.isFinite(Number(entry.stickyLimit)) && Number(entry.stickyLimit) > 0 ? Math.trunc(Number(entry.stickyLimit)) : 1\n  const cursor = rotation.get(entry.id) ?? { index: 0, used: 0 }\n  const index = Math.min(Math.max(cursor.index, 0), members.length - 1)\n  const ordered = [...members.slice(index), ...members.slice(0, index)]\n  if (options.peek !== true) {\n    const used = cursor.used + 1\n    rotation.set(entry.id, used >= limit ? { index: (index + 1) % members.length, used: 0 } : { index, used })\n  }\n  return ordered\n}\n\n/** Drop rotation cursors for combos that no longer exist, so the map cannot grow forever. */\nexport function pruneRotation(combos) {\n  const live = new Set(combos.map(combo => combo.id))\n  for (const key of rotation.keys()) if (!live.has(key)) rotation.delete(key)\n}\n\n/** Test seam: the rotation map is process state. */\nexport function resetRotation() {\n  rotation.clear()\n}\n"
